SELECT FROM enterprise_profile WHERE tenant_id IN
#{id}
AND is_deleted = 0

SELECT id, tenant_id, profile_type, company_name, province, city, sup_categories, sup_capacity, sup_certs, sup_export, main_products, industry, key_clients, lead_time, completeness_score, perf_score, perf_sample_size, reg_number, established_year FROM enterprise_profile WHERE profile_type IN ('supplier', 'both') AND is_deleted = 0
AND tenant_id != #{excludeTenantId}
AND (
sup_categories LIKE CONCAT('%', #{tok}, '%')
)
AND (province LIKE CONCAT('%', #{region}, '%') OR city LIKE CONCAT('%', #{region}, '%'))
ORDER BY completeness_score DESC LIMIT #{limit}

SELECT ep.id, ep.tenant_id, ep.profile_type, ep.company_name, ep.industry, ep.province, ep.city, ep.sup_categories, ep.sup_capacity, ep.sup_certs, ep.sup_export, ep.main_products, ep.key_clients, ep.lead_time, ep.description, ep.contact_name, ep.contact_phone, ep.contact_email, ep.buy_categories, ep.buy_volume, ep.buy_volume_amount, ep.buy_volume_currency, ep.fiscal_period_start, ep.fiscal_period_end, ep.reg_number, ep.established_year, ep.create_time, ep.update_time, ep.is_deleted FROM enterprise_profile ep WHERE ep.profile_type IN ('supplier', 'both') AND ep.is_deleted = 0
AND ep.tenant_id != #{excludeTenantId}
AND (ep.company_name LIKE CONCAT('%', #{keyword}, '%') OR ep.industry LIKE CONCAT('%', #{keyword}, '%') OR ep.province LIKE CONCAT('%', #{keyword}, '%') OR ep.sup_categories LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY ep.create_time DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM enterprise_profile WHERE profile_type IN ('supplier', 'both') AND is_deleted = 0
AND tenant_id != #{excludeTenantId}
AND (company_name LIKE CONCAT('%', #{keyword}, '%') OR industry LIKE CONCAT('%', #{keyword}, '%') OR province LIKE CONCAT('%', #{keyword}, '%') OR sup_categories LIKE CONCAT('%', #{keyword}, '%'))
